const utils = global.get("utils");
const source_attr = utils.get_system_attributes(msg.metadata.source.client_system);
const target_attr = utils.get_system_attributes(msg.metadata.target.client_system);

const can_transfer = source_attr.can_upload && target_attr.can_download;

const files = msg.payload.files || [];
const items = [];
const failed = [];

if (!can_transfer) {
    files.forEach(file => {
        failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.NON_TRANSFERABLE });
    });
} else {
    files.forEach(file => {
        if (msg.metadata.source.client_system === "rayvn"
            && file.url && file.url.includes("rayvn.global")
            && !file.url.includes("sig=")) {
            failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.NON_TRANSFERABLE });
            return;
        }
        if (target_attr.max_upload_bytes && file.size && file.size > target_attr.max_upload_bytes) {
            file.reason = utils.FILE_REASONS.OVERSIZED;
        }
        items.push(file);
    });
}


msg.metadata.files = { items, failed };

if (items.length > 0) return [msg, null];
return [null, msg];
